        // ================================ (b)/(c) UKF agrees with the linear KF =====================
        // Sigma points transformed through an EXACTLY LINEAR F/H reproduce the linear Kalman filter's
        // mean/covariance recursion exactly (up to roundoff) regardless of alpha/beta/kappa -- the
        // strongest available correctness oracle, since it does not depend on the pendulum model's own
        // nonlinearity being "small enough". Two independent state/cache instances run the SAME
        // measurement stream side by side.
        void UKFAgreesWithLinearKF()
        {
            BuildCV(out var A, out var H, out var Q, out var R);

            var sLin = new floatKFState(2, 1, Allocator.Temp);
            var sUkf = new floatKFState(2, 1, Allocator.Temp);
            sLin.x[0] = (float)0; sLin.x[1] = (float)0; sLin.P[0, 0] = (float)5; sLin.P[1, 1] = (float)5;
            sUkf.x[0] = (float)0; sUkf.x[1] = (float)0; sUkf.P[0, 0] = (float)5; sUkf.P[1, 1] = (float)5;

            var cache = new floatUKFCache(2, Allocator.Temp);   // library defaults: alpha=1, beta=2, kappa=0
            var model = new floatLinearCVModel { A = A };
            var meas = new floatLinearPosMeas { Hmat = H };
            var u = new floatN(1, Allocator.Temp);

            var trueState = new floatN(2, Allocator.Temp);
            trueState[0] = (float)0; trueState[1] = (float)0.5;
            var trueNext = new floatN(2, Allocator.Temp);
            var z = new floatN(1, Allocator.Temp);
            var rng = new Unity.Mathematics.Random(0xC0FFEEu);

            float maxXDiff = 0, maxPDiff = 0;
            int steps = 60;
            for (int k = 0; k < steps; k++)
            {
                Blas.dot(in A, in trueState, ref trueNext);
                trueState.Data.CopyFrom(trueNext.Data);
                z[0] = trueState[0] + (float)rng.NextFloat(-0.2f, 0.2f);

                Kalman.predict(ref sLin, in A, in Q);
                var infoLin = Kalman.update(ref sLin, in H, in R, in z);
                AssertTrue(infoLin.status == KFStatus.Ok);

                Kalman.ukfPredict(ref sUkf, ref cache, in model, in u, in Q);
                var infoUkf = Kalman.ukfUpdate(ref sUkf, ref cache, in meas, in R, in z);
                AssertTrue(infoUkf.status == KFStatus.Ok);

                for (int i = 0; i < 2; i++)
                {
                    float d = math.abs(sLin.x[i] - sUkf.x[i]);
                    if (d > maxXDiff) maxXDiff = d;
                }
                for (int i = 0; i < 2; i++)
                    for (int j = 0; j < 2; j++)
                    {
                        float d = math.abs(sLin.P[i, j] - sUkf.P[i, j]);
                        if (d > maxPDiff) maxPDiff = d;
                    }
            }

            AssertClose(maxXDiff, (float)0, XAgreeTol());
            AssertClose(maxPDiff, (float)0, PAgreeTol());

            sLin.Dispose(); sUkf.Dispose(); cache.Dispose();
            A.Dispose(); H.Dispose(); Q.Dispose(); R.Dispose();
            u.Dispose(); trueState.Dispose(); trueNext.Dispose(); z.Dispose();
        }

        // ================================ (a) UKF tracks a nonlinear pendulum ========================
        // Same pendulum scenario as KalmanTests.EKFTracksNonlinear (wrong initial angle, nonlinear
        // dynamics + nonlinear sin(theta) measurement) -- UKF must meet the SAME bounded-error bar
        // (prototype-validated to be as good as or better than the EKF on this exact model).
        void UKFTracksPendulum()
        {
            var model = new floatPendulumModel { dt = (float)0.05, gOverL = (float)4 };
            var meas = new floatPendulumMeas();

            var Q = new floatMxN(2, 2, Allocator.Temp); Q[0, 0] = (float)1e-6; Q[1, 1] = (float)1e-6;
            var R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = (float)1e-3;
            var u = new floatN(1, Allocator.Temp);

            var s = new floatKFState(2, 1, Allocator.Temp);
            s.x[0] = (float)0; s.x[1] = (float)0;    // wrong initial angle (truth 0.3)
            s.P[0, 0] = (float)0.5; s.P[1, 1] = (float)0.5;
            var cache = new floatUKFCache(2, Allocator.Temp);

            var trueState = new floatN(2, Allocator.Temp); trueState[0] = (float)0.3; trueState[1] = (float)0;
            var trueNext = new floatN(2, Allocator.Temp);
            var zTrue = new floatN(1, Allocator.Temp);
            var z = new floatN(1, Allocator.Temp);
            var rng = new Unity.Mathematics.Random(0xECF00Du);

            for (int k = 0; k < 80; k++)
            {
                model.F(in trueState, in u, ref trueNext);
                trueState.Data.CopyFrom(trueNext.Data);

                meas.H(in trueState, ref zTrue);
                z[0] = zTrue[0] + (float)rng.NextFloat(-0.02f, 0.02f);

                Kalman.ukfPredict(ref s, ref cache, in model, in u, in Q);
