            AssertClose(s.x[0], trueState[0], EkfThetaTol());
            AssertClose(s.x[1], trueState[1], EkfOmegaTol());

            s.Dispose(); cache.Dispose(); Q.Dispose(); R.Dispose(); u.Dispose();
            trueState.Dispose(); trueNext.Dispose(); zTrue.Dispose(); z.Dispose();
        }

