        // ================================ ukfUpdate failure path ====================================
        // A negative R (mirrors KalmanTests.UpdateFailureLeavesState) makes Pzz indefinite -> CHOP
        // reports Indefinite -> KFStatus.InnovationSolveFailed. x/P must be byte-identical to their
        // pre-update values.
        void UpdateFailureLeavesState()
        {
            var H = new floatMxN(1, 2, Allocator.Temp); H[0, 0] = (float)1; H[0, 1] = (float)0;
            var R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = (float)(-2);
            var meas = new floatLinearPosMeas { Hmat = H };
            var z = new floatN(1, Allocator.Temp); z[0] = (float)3;

            var s = new floatKFState(2, 1, Allocator.Temp);
            s.x[0] = (float)7; s.x[1] = (float)(-4);
            s.P[0, 0] = (float)1; s.P[0, 1] = (float)0; s.P[1, 0] = (float)0; s.P[1, 1] = (float)1;
            var cache = new floatUKFCache(2, Allocator.Temp);

            var xSnap = new floatN(2, Allocator.Temp); xSnap.Data.CopyFrom(s.x.Data);
            var pSnap = new floatMxN(in s.P, Allocator.Temp);

            var info = Kalman.ukfUpdate(ref s, ref cache, in meas, in R, in z);

            AssertTrue(info.status == KFStatus.InnovationSolveFailed);
            AssertTrue(!info.Solved);
            for (int i = 0; i < 2; i++)
                AssertTrue(s.x[i] == xSnap[i]);
            for (int i = 0; i < 2; i++)
