                    AssertTrue(s.P[i, j] == pSnap[i, j]);

            s.Dispose(); cache.Dispose(); H.Dispose(); R.Dispose(); z.Dispose(); xSnap.Dispose(); pSnap.Dispose();
        }

        // ================================ helpers ================================

        static void BuildCV(out floatMxN A, out floatMxN H, out floatMxN Q, out floatMxN R)
