            A = new floatMxN(2, 2, Allocator.Temp);
            A[0, 0] = (float)1; A[0, 1] = (float)1; A[1, 0] = (float)0; A[1, 1] = (float)1;
            H = new floatMxN(1, 2, Allocator.Temp); H[0, 0] = (float)1; H[0, 1] = (float)0;
            Q = new floatMxN(2, 2, Allocator.Temp); Q[0, 0] = (float)1e-4; Q[1, 1] = (float)1e-4;
            R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = (float)0.05;
        }

        // ---- Fail[0..3] diagnostic asserts (same shape as KalmanTests.float.cs) ----
        void AssertTrue(bool cond)
        {
            if (!cond && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = (float)0; Fail[2] = (float)1; Fail[3] = (float)0; }
            Assert.IsTrue(cond);
        }

        void AssertExactSymPosDiag(in floatMxN P)
        {
            int n = P.M_Rows;
            for (int i = 0; i < n; i++)
            {
                if (!(P[i, i] > (float)0) && Fail[0] == (float)0)
                { Fail[0] = (float)1; Fail[1] = P[i, i]; Fail[2] = (float)0; Fail[3] = P[i, i]; }
                Assert.IsTrue(P[i, i] > (float)0);
                for (int j = i + 1; j < n; j++)
                {
                    bool sym = P[i, j] == P[j, i];
                    if (!sym && Fail[0] == (float)0)
                    { Fail[0] = (float)1; Fail[1] = P[i, j]; Fail[2] = P[j, i]; Fail[3] = P[i, j] - P[j, i]; }
                    Assert.IsTrue(sym);
                }
            }
        }

        void AssertClose(float a, float b, float precision)
        {
            float diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = a; Fail[2] = b; Fail[3] = diff; }
            Assert.IsTrue(diff <= precision);
        }
