    // ---- linear model/measurement struct-functors (nested so codegen renames the enclosing generic
    //      type per dtype, avoiding a float/double name collision) ----

    public struct floatLinearCVModel : IfloatKFModel
    {
        public floatMxN A;

        public void F(in floatN x, in floatN u, ref floatN xNext) => Blas.dot(in A, in x, ref xNext);

        public void JacobianF(in floatN x, in floatN u, ref floatMxN J)
        {
            for (int i = 0; i < A.M_Rows; i++)
                for (int j = 0; j < A.N_Cols; j++)
                    J[i, j] = A[i, j];
        }
    }

    public struct floatLinearPosMeas : IfloatKFMeasurement
    {
        public floatMxN Hmat;

        public void H(in floatN x, ref floatN z) => Blas.dot(in Hmat, in x, ref z);

        public void JacobianH(in floatN x, ref floatMxN J)
        {
            for (int i = 0; i < Hmat.M_Rows; i++)
                for (int j = 0; j < Hmat.N_Cols; j++)
                    J[i, j] = Hmat[i, j];
        }
    }

    // Pendulum dynamics: state [theta, omega], control ignored (autonomous). Same model as
    // KalmanTests.floatPendulumModel/floatPendulumMeas, duplicated here to keep this file
    // self-contained.
    public struct floatPendulumModel : IfloatKFModel
    {
        public float dt;
        public float gOverL;

        public void F(in floatN x, in floatN u, ref floatN xNext)
        {
            float th = x[0], om = x[1];
            xNext[0] = th + om * dt;
            xNext[1] = om - gOverL * math.sin(th) * dt;
        }

        public void JacobianF(in floatN x, in floatN u, ref floatMxN J)
        {
            float th = x[0];
            J[0, 0] = (float)1; J[0, 1] = dt;
            J[1, 0] = -gOverL * math.cos(th) * dt; J[1, 1] = (float)1;
        }
    }

    public struct floatPendulumMeas : IfloatKFMeasurement
    {
        public void H(in floatN x, ref floatN z)
        {
            z[0] = math.sin(x[0]);
        }

        public void JacobianH(in floatN x, ref floatMxN J)
        {
            J[0, 0] = math.cos(x[0]); J[0, 1] = (float)0;
        }
    }

