    [Test]
    public void UKFCacheThrowsOnBadHyperparameters()
    {
        // alpha=0 -> lambda = -n -> n+lambda = 0, not > 0.
        Assert.Catch<ArgumentException>(() => new floatUKFCache(2, (float)0, (float)2, (float)0, Allocator.Temp));
    }

    [Test]
    public void UkfThrowsOnDimensionMismatch()
    {
        var s = new floatKFState(2, 1, Allocator.Temp);
        var A = new floatMxN(2, 2, Allocator.Temp);
        A[0, 0] = (float)1; A[0, 1] = (float)1; A[1, 0] = (float)0; A[1, 1] = (float)1;
        var model = new floatLinearCVModel { A = A };
        var u = new floatN(1, Allocator.Temp);
        var Q = new floatMxN(2, 2, Allocator.Temp); Q[0, 0] = (float)1e-4; Q[1, 1] = (float)1e-4;

        // cache sized for n=3 used against a state sized for n=2 -> throws
        var cacheWrongN = new floatUKFCache(3, Allocator.Temp);
        Assert.Catch<ArgumentException>(() => Kalman.ukfPredict(ref s, ref cacheWrongN, in model, in u, in Q));

        var H = new floatMxN(1, 2, Allocator.Temp); H[0, 0] = (float)1;
        var meas = new floatLinearPosMeas { Hmat = H };
        var R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = (float)0.05;
        var z = new floatN(1, Allocator.Temp);
        Assert.Catch<ArgumentException>(() => Kalman.ukfUpdate(ref s, ref cacheWrongN, in meas, in R, in z));

        var cacheGood = new floatUKFCache(2, Allocator.Temp);
        var Qbad = new floatMxN(3, 3, Allocator.Temp);
        Assert.Catch<ArgumentException>(() => Kalman.ukfPredict(ref s, ref cacheGood, in model, in u, in Qbad));

        var Rbad = new floatMxN(2, 2, Allocator.Temp);
        Assert.Catch<ArgumentException>(() => Kalman.ukfUpdate(ref s, ref cacheGood, in meas, in Rbad, in z));

        s.Dispose(); A.Dispose(); u.Dispose(); Q.Dispose(); Qbad.Dispose();
        H.Dispose(); R.Dispose(); Rbad.Dispose(); z.Dispose();
        cacheWrongN.Dispose(); cacheGood.Dispose();
    }
